(1389172, 'रिपोर्टिंग लाइव', 'Kejahatan', 116, 'NR', 'A young reporter and her reluctant cameraman chase a story, only to get entangled in an illegal sand-mining racket run by a ruthless syndicate.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/72ETmrsQGk8guVo1GV8Sf7EygOe.jpg', 'https://image.tmdb.org/t/p/w1280/faJB8DXU0LXwq5ebMLj5drz8S4N.jpg', 8.1, 'GgGNG9XEJds', '2026-10-09', 126.334, 4, 'tt47657999', null, null, null, null),
(1232569, 'Pinocchio: Unstrung', 'Kengerian', 82, 'NR', 'Influenced by a sinister Cricket and created by Geppetto, Pinocchio launches a violent crusade to carve himself into a real boy like his brother James, one piece at a time.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/hJNdizFlxOW89edX3Rzr6OliSFI.jpg', 'https://image.tmdb.org/t/p/w1280/7RsPdXLDNugDIlwXPVeeprNfMx.jpg', 6.5, 'Y4lZewE6JMI', '2026-07-22', 114.25, 135, 'tt30887701', 5.4, 4534, 'R', null),
(1514026, 'Buddy', 'Kengerian', 96, 'NR', 'A magical, singing orange unicorn holds his cast hostage in a surreal TV-show dimension, as he becomes more and more demented.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/1BdZbNvl1SfrrX8J9X5tQzN6Ivu.jpg', 'https://image.tmdb.org/t/p/w1280/kghxBvN7f3vUt377yjO4ygbefYN.jpg', 7.3, null, '2026-08-27', 111.507, 111, 'tt37281055', 7.1, 5019, 'R', 2063),
(1288445, 'Mutiny', 'Aksi', 96, 'NR', 'After witnessing his billionaire boss'' murder and being framed for the crime, Cole Reed boards a cargo ship on a one-man crusade to avenge his boss'' death only to discover an international conspiracy.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/pu2VxGlpGwffOx292w18b1tv96j.jpg', 'https://image.tmdb.org/t/p/w1280/e2QAGrEmbpmZpMymDRkDisJkvg9.jpg', 7.6, '2Iqvbe98Gb4', '2026-08-19', 111.429, 890, 'tt32338669', 5.7, 17192, 'R', 1235),
(1742441, 'V/H/S/Mixtape', 'Kengerian', 98, 'NR', 'V/H/S/MIXTAPE cranks the volume on horror with a blood-soaked collection of cursed music videos, terrifying performances, and found footage. Press play. Pray it stops.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/uS8yoiA6NfsuYeOTbVfpem8Ib9.jpg', 'https://image.tmdb.org/t/p/w1280/mpB4pgtUcc7rCLxvlknzCbAQQEE.jpg', 4.5, 'GrIouRKyPDw', '2026-10-09', 105.677, 21, 'tt43739386', 6.7, 73, null, 809),
(1280300, 'The Whistler', 'Misteri', 97, 'NR', 'Reeling from their daughter''s loss, Nicole and Sebastian come into possession of a secluded Venezuelan farm, unaware of the dark forces they''re about to face.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/sX8tqkFR1aqZaLQ4Jgb8jEMB4RN.jpg', 'https://image.tmdb.org/t/p/w1280/qz8m7DGpuhc4RJmCbHsdueQKkTg.jpg', 5, '8PNnVN8NSHk', '2026-09-24', 95.119, 3, 'tt1776340', null, null, null, null),
(977942, 'The Uprising', 'Aksi', 128, 'NR', 'As war and plague devastate 14th-century England, a humble peasant ignites a rebellion, uniting an army of commoners to defy the King’s might in a desperate fight for justice and survival.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/7TUl15TOsIvndKlgMWTtLgtEzZP.jpg', 'https://image.tmdb.org/t/p/w1280/y0reRTsewsPh0ePtgvDeLIsb5Wk.jpg', 7.9, 'lyhCxZN4Ro8', '2026-09-10', 104.969, 323, 'tt36983905', null, null, 'R', 3240),
(1275779, 'Disclosure Day', 'Cerita Fiksi', 146, 'NR', 'Jika Anda mengetahui bahwa kita tidak sendirian, jika seseorang menunjukkannya kepada Anda, membuktikannya kepada Anda, apakah itu akan membuat Anda takut?', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/AnJ8IQJI23hNpYXVNaythu061Ru.jpg', 'https://image.tmdb.org/t/p/w1280/1e0KDRYKRPHiVNj8yQKYuU2jVyQ.jpg', 7.4, 'icDuEHSxE-w', '2026-06-10', 98.54, 3672, 'tt15047880', 6.4, 164418, 'PG-13', 2129),
(1273221, 'Scary Movie', 'Komedi', 96, 'NR', 'Twenty-six years after outrunning a suspiciously familiar masked killer, the Core Four are back in the killer''s crosshairs and no horror movie IP is safe.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/znHT8peERZRWG1ME3r0Db0EV8k8.jpg', 'https://image.tmdb.org/t/p/w1280/xWBiXclrRmTggQHMRsIn84YHavs.jpg', 6.3, 'cGgWAHXuTKc', '2026-06-03', 80.715, 2029, 'tt32093575', 4.8, 61113, 'R', 674),
(1032863, 'Hipotesis Cinta', 'Percintaan', 112, 'NR', 'Berdasarkan novel laris New York Times, Hipotesis Cinta menceritakan Olive, calon Ph.D. yang spontan mencium profesor paling galak di departemennya, Adam Carlsen. Kebutuhan bersama mereka untuk hubungan palsu berubah menjadi eksperimen kecocokan yang mungkin memecahkan masalah cinta.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/jQol5xRU1e0JOL0ki4kDioj66Ah.jpg', 'https://image.tmdb.org/t/p/w1280/o7Oy9Gbx1CCyaweL8xUhtMW4Puq.jpg', 8, 'xwdamnfS6IM', '2026-09-23', 76.382, 606, 'tt22526100', null, null, 'R', 3051),
(1375161, 'Don''t Move', 'Kengerian', 94, 'NR', 'A church group''s annual retreat turns deadly when they wander into the wrong part of the Ozark wilderness, and something starts picking them off one by one. Suspicion falls on Ricky, the troublemaker of the group. But the real threat is far worse. Deep in the forest, wrapped in a labyrinth of webs, the group is pursued by a terrifying prehistoric arachnid that hunts by vibration. When every step could be their last, they only have one choice: Don''t Move. It''s up to Megan to hold what''s left of the group together and get them out alive.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/uh0ZSdM8iOQgHwnUlhhanP8Dkl6.jpg', 'https://image.tmdb.org/t/p/w1280/1b0RrVxLAMhfT0vQXfWtDLwg1ke.jpg', 5.4, 'FwoYYKyJo1g', '2026-09-11', 90.218, 13, 'tt29630464', 6.7, 34, null, null),
(9479, 'The Nightmare Before Christmas', 'Fantasi', 76, 'NR', 'Tired of scaring humans every October 31 with the same old bag of tricks, Jack Skellington, the spindly king of Halloween Town, kidnaps Santa Claus and plans to deliver shrunken heads and other ghoulish gifts to children on Christmas morning. But as Christmas approaches, Jack''s rag-doll girlfriend, Sally, tries to foil his misguided plans.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/oQffRNjK8e19rF7xVYEN8ew0j7b.jpg', 'https://image.tmdb.org/t/p/w1280/dSfrsjhqC6lYe7LYDYnzWeXZmEl.jpg', 7.9, 'IoYahD_xNR0', '1993-10-09', 85.065, 10730, 'tt0107688', 7.9, 416592, 'PG', 747),
(3933, 'Corpse Bride', 'Percintaan', 77, 'NR', 'Aksinya berlangsung di sebuah desa Eropa pada abad ke-19. Tokoh utama, seorang pemuda bernama Victor, diseret ke dunia bawah oleh kekuatan kegelapan dan dinikahkan di sana dengan Pengantin Mayat yang misterius, sementara pengantin perempuannya yang sebenarnya, Victoria, menanti pengantin prianya di dunia orang hidup. Meskipun kenyataan bahwa tinggal di Kerajaan Orang Mati ternyata jauh lebih menarik daripada gaya hidup Victoria yang biasa ia jalani, Victor memahami bahwa ia tidak akan menukar satu-satunya cintanya dengan apa pun di dunia alternatif mana pun...', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/3RAoVTxUk1OzZClscAsynuu670p.jpg', 'https://image.tmdb.org/t/p/w1280/v23fWgJUEt8EMmvn19btIacxP8E.jpg', 7.6, 'BgwJEpmPKk8', '2005-09-12', 87, 10500, 'tt0121164', 7.4, 333077, 'PG', null),
(1607127, 'One Last Shot', 'Aksi', 98, 'NR', 'Navy Seal Jake Harris must stop a team of mercenaries, led by his disillusioned former comrade, from disabling the US missile defense network.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/niQ4NBh2jqAf1hDZP5m6ReWFAb7.jpg', 'https://image.tmdb.org/t/p/w1280/8giIQcHpxgsPVP6c7aQtHl3txuh.jpg', 7.4, '8PAy3i9uU0A', '2026-09-22', 84.806, 124, 'tt37971717', null, null, 'R', null),
(1375646, '군체', 'Kengerian', 123, 'NR', 'Professor Se-jeong is thrust into a bloody nightmare when a rapidly mutating virus is released during a biotech conference causing authorities to seal the facility. Trapped inside with no escape, Se-jeong along with a small group of survivors must fight to stay alive while the infected undergo horrific transformations.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/thK6glS5pklrlijsgSN6Hw9GLQK.jpg', 'https://image.tmdb.org/t/p/w1280/pGxUbJ1vKuMYeEjKDokFI7DNbSG.jpg', 8.1, 'LW6dpj1uCK8', '2026-05-21', 80.436, 1157, 'tt34385135', 6.5, 18328, 'R', 926),
(843352, 'Legend of the White Dragon', 'Aksi', 97, 'NR', 'Forced to hide in the shadows, fugitive hero Erik Reed must clear his name to reunite with his family. Standing in his way is a mysterious villain obsessed with destroying the White Dragon for good.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/yygzww0GACtCMmwhtPG1P01qSx5.jpg', 'https://image.tmdb.org/t/p/w1280/iBfpVJCn2nKSkuWjv1Wp4GTiqoG.jpg', 6.8, 'eqcTr34Y1Zw', '2026-08-28', 75.575, 67, 'tt12446086', 5.6, 387, 'R', null),
(1327819, 'Hoppers', 'Petualangan', 104, 'NR', 'Para ilmuwan telah menemukan cara untuk ''mentransfer'' kesadaran manusia ke dalam hewan robot yang menyerupai manusia., Memungkinkan manusia untuk berkomunikasi dengan hewan sebagai hewan. Mabel, seorang pencinta hewan, memanfaatkan kesempatan untuk menggunakan teknologi tersebut. Mengungkap misteri di dunia hewan yang melampaui apa pun yang pernah dia bayangkan.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/xjtWQ2CL1mpmMNwuU5HeS4Iuwuu.jpg', 'https://image.tmdb.org/t/p/w1280/u53UYu5XG2hNgWGvs3xGhAVzypl.jpg', 8.1, 'PypDSyIRRSs', '2026-03-04', 63.226, 2436, 'tt26443616', 7.2, 87615, 'PG', null),
(14836, 'Coraline', 'Animasi', 100, 'NR', 'Wandering her rambling old house in her boring new town, 11-year-old Coraline discovers a hidden door to a strangely idealized version of her life. In order to stay in the fantasy, she must make a frighteningly real sacrifice.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/4jeFXQYytChdZYE9JYO7Un87IlW.jpg', 'https://image.tmdb.org/t/p/w1280/hofnlIyF6bePkgQOpcuRWLvzf15.jpg', 7.9, 'T6iQnnHNF50', '2009-02-05', 70.817, 9568, 'tt0327597', 7.8, 307662, 'PG', 830),
(1083381, 'Backrooms', 'Kengerian', 111, 'NR', 'Setelah pasien seorang terapis menghilang ke dimensi di luar realitas, dia harus menjelajah ke tempat yang tidak dikenal untuk menyelamatkannya.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/rhGx6E3qRNMgj3i5su2oukNHwIQ.jpg', 'https://image.tmdb.org/t/p/w1280/dqmMWNWfLnExDRpMtIMqI97GQFR.jpg', 7, '0HjdiohVOik', '2026-05-27', 80.1, 3740, 'tt26657236', 6.7, 221583, 'R', 2143),
(131631, 'The Hunger Games: Mockingjay - Part 1', 'Cerita Fiksi', 123, 'NR', 'Katniss, yang kembali ke Distrik 13 setelah menghancurkan Hunger Games, dengan berat hati menjadi ikon gelombang pemberontakan melawan Capitol.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/4FAA18ZIja70d1Tu5hr5cj2q1sB.jpg', 'https://image.tmdb.org/t/p/w1280/lV1P1Q5gLDXVG1ZYCxZHStkcQC3.jpg', 6.8, 'IXshQ5mv1K8', '2014-11-19', 69.98, 17097, 'tt1951265', 6.6, 555128, 'PG-13', null),
(1476746, 'The Florist', 'Aksi', 99, 'NR', 'A quiet horticulturalist harboring a secret life as a lethal assassin finds his true identity jeopardized when he forms an unlikely friendship with a witnesses to police corruption.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/4tnRvIiWMzVA2Tw9c7INLo4sfo0.jpg', 'https://image.tmdb.org/t/p/w1280/jpH1VRw74w0vvPTY0ryKEtMIXc.jpg', 6.7, 'LNmIdALXoKo', '2026-09-24', 72.113, 19, 'tt33214716', null, null, null, 1096),
(1590723, 'Laut Bercerita', 'Drama', 133, 'NR', 'Set during the volatile final months of Indonesia’s New Order regime, the narrative chronicles a young student activist''s perilous commitment to pro-democracy underground movements and his family''s subsequent, grueling quest for justice following his forced disappearance.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/8FqJSSMPaKJzqq2VVxVmdHUozLY.jpg', 'https://image.tmdb.org/t/p/w1280/dibjzvhuz4FiF0Af9BkcMDHRSCD.jpg', null, 'Crx2f2CvUpc', '2026-10-29', 5.465, 0, 'tt39073337', null, null, 'TV-MA', null),
(1590752, 'Pulang Kampung', 'Musik', 100, 'NR', 'Dalam rangka menjadi Caleg sesuai perintah ayahnya, Daniel, pemuda Batak kelahiran Jakarta, terpaksa pulang kampung untuk belajar budaya Batak ditemani Uli, sepupunya yang tinggal di Danau Toba. Masalah muncul ketika Daniel ternyata bukan cuma jatuh cinta pada budaya Batak, tapi juga pada Uli.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/wsipU0tvTmrSTsBh7pe6r8pk58z.jpg', null, null, 'JkiJTQXe8Lo', '2026-11-26', 3.742, 0, 'tt39073352', null, null, null, null),
(1763612, 'Orang Sebelah', 'Kengerian', 100, 'NR', 'This film is based on one of the well-known, spine-chilling myths circulating around the IPB University campus area that haunts the students living in the campus dorms.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/kmM5kbjlD46Hon1oUG3I0BbTFxz.jpg', null, null, null, '2026-11-26', 3.2, 0, null, null, null, null, null),
(1679486, 'People Pleaser: Si Paling Gak Enakan', 'Drama', 100, 'NR', 'Sinopsis belum tersedia.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/j2oxt48zdUPbJdnoiCTCOURIj22.jpg', 'https://image.tmdb.org/t/p/w1280/saHUIv7DClJ0fLDc4lfxHdSxBm1.jpg', null, 'rtBBEtosXMc', '2026-11-19', 2.894, 0, null, null, null, null, null),
(1691495, 'Hajatan Setan', 'Kengerian', 100, 'NR', 'A young woman returns to her hometown after being away for years. However, her homecoming reopens old wounds and triggers a series of strange events that slowly engulf the villagers in suspicion and fear.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/eJvErXsnBM2PgfmXsvdCVmKDJH6.jpg', 'https://image.tmdb.org/t/p/w1280/kOtozhUgLfjPeCTit6X4hMVzaq4.jpg', null, null, '2026-12-03', 2.537, 0, null, null, null, null, null),
(1450848, 'Dua Hati Ibu', 'Drama', 102, 'NR', 'Two childless married couples raise an unexpected son from an illicit affair between the two households. Amidst the chaos that follows a paternity reveal, the two wives take parenting into their own hands.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/ugFHOSdCSk2I4FbTz9pXPqxrq9H.jpg', 'https://image.tmdb.org/t/p/w1280/yW9RjrPketD2Kz3Y6q3eIpIC2I2.jpg', null, null, '2026-10-23', 3.097, 0, 'tt38773553', null, null, null, null),
(1551036, 'Seporsi Mie Ayam Sebelum Mati', 'Drama', 125, 'NR', 'If today were your last day, what one small thing would you really want to do? For Ale, the answer is simple: enjoy a bowl of his favorite chicken noodles before he truly gives up on life. But when his regular food cart is closed, that situation leads him into a series of unexpected encounters.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/wqfi1Cicqj1Y6sDxQYSaRihw6IJ.jpg', 'https://image.tmdb.org/t/p/w1280/rQD4rMpygqw3z9ZJMSkz6h6tSJ4.jpg', null, 'yESY1GP1mfQ', '2026-11-12', 2.975, 0, 'tt45292829', null, null, null, null),
(1757259, 'Rambut Sewu: Satu Langkah Getih', 'Kengerian', 100, 'NR', 'Wulan (Wavi Zihan) moves to a village with her mother, Ratih (Ruth Marini). After working at a tea factory, they move into an old house owned by the company. From then on, Wulan begins to experience strange dreams and mysterious events, eventually losing control of herself. The villagers attribute these disturbances to Marni (Taskya Namya), a former resident of the house whose story has remained a mystery for decades. When Wulan’s story spreads on social media, Damar (Yusuf Mahardika), a reporter and native son of the village, arrives to investigate. Suradi (Donny Alamsyah), who is aware of the powers of the past, comes to help. Together, they try to sever Wulan’s connection to Marni and the power of Dhandhang Gendhing.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/n2j1EDgh818ZYRVZeasJul2Pbmk.jpg', null, null, null, '2026-11-05', 2.136, 0, null, null, null, null, null),
(1763585, 'Lagi Probation: Kerja Ngejar Apa Sih?', 'Drama', 100, 'NR', 'Bintang harus cari kerjaan untuk hidupin keluarga dan dirinya sendiri. Setelah berjuang sana-sini, kesempatan langka akhirnya datang: Bintang diterima jadi anak probation alias magang di perusahaan bumbu dapur besar, bersama Bima si Cumlaude, Velma si Asbun, Damai si Cari Muka, Mika si Pewaris, dan Claudia si Robot Korporat. Tapi, baru juga bonding sama teman-teman barunya, eh ternyata cuma satu yang akan lolos probation dan jadi karyawan tetap. Seketika, teamwork berubah jadi team-war, teman jadi saingan, kolaborasi jadi kompetisi. 6 orang, 1 posisi. Siapa yang akan berhasil?', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/4glDFxFmu3GyX9N50EtiLk0k8zp.jpg', 'https://image.tmdb.org/t/p/w1280/olkdII9tRfrQ84ne8d44h7LrXbz.jpg', null, 'QA8NwVVZguw', '2026-11-12', 2.414, 0, null, null, null, null, null),
(1605869, 'Beneran Horor', 'Komedi', 100, 'NR', 'Sinopsis belum tersedia.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/lUKkgheFwpt8GQDTLeESdtKs8w0.jpg', null, null, null, '2026-12-31', 2.2, 0, null, null, null, null, null),
(1607692, '5 cm: Revolusi Hati', 'Petualangan', 100, 'NR', 'Four inseparable companions pledge lifelong solidarity upon entering secondary education, only for their collective bond to undergo severe emotional and structural strain when the introduction of romantic interests and an transformative journey outside the metropolis force them to confront the inevitable realities of maturity.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/mrrEHOCeaRsybiny0G64IGQRTYw.jpg', null, null, null, '2026-12-24', 2.165, 0, null, null, null, null, null),
(1770196, 'Gak Masuk Akal', 'Drama', 100, 'NR', 'Plot under wraps.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/wUAPHEZV3BBXYUeSCrmZ1idSKHD.jpg', null, null, null, '2027-01-07', 2.029, 0, null, null, null, null, null),
(1398505, 'Desember Jani', 'Drama', 101, 'NR', 'Sepuluh hari setelah Julia pergi dari rumah tanpa pamit, Jani (13 tahun) cuma ingin kakaknya itu pulang. Ia tahu ibunya, Winnie, adalah penyebab Julia pergi. Hubungan mereka makin renggang, sementara Winnie sibuk bekerja untuk menutupi rasa bersalahnya. Hanya Oma yang bisa menghibur Jani. Diam-diam, Jani masih berhubungan dengan Julia. Selama empat hari di bulan Desember, Jani harus memilih: tetap diam atau menghadapi ibunya.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/rmF3JezLg5ZpFmvOXy50gTwGaWE.jpg', null, null, '9eQFxRmw9g8', '2026-12-10', 2.192, 0, 'tt39673642', null, null, 'TV-G', null),
(1675781, 'Harga Teman', 'Drama', 118, 'NR', 'After getting fired, Uji, a graphic designer, teams up with her three closest friends to start a creative agency. Amid client demands, family expectations, and friendship dilemmas, she hopes this could be a new beginning. But deeper she goes, the more she realizes: every relationship has its price, friendship included.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/oakfm5GZbxI1U32WC3eudQJq0D8.jpg', 'https://image.tmdb.org/t/p/w1280/c7Y2J5fPvUsj125icXshzCPbxq9.jpg', null, null, '2026-10-23', 1.89, 0, 'tt41941030', null, null, null, null),
(1589640, 'Dewi Siluman Ular', 'Kengerian', 100, 'NR', 'Dedi, a man who is bankrupt and deep in debt, performs a ritual to marry a beautiful jinn named Dewi in order to get the money to pay off his debts—with one condition: he must never marry anyone else. As Dedi grows richer and more prosperous, he suddenly falls in love with a woman and intends to marry her. Dewi becomes furious because Dedi has forgotten the condition of the ritual, and eventually, a series of terrifying events threatens the lives of those closest to Dedi.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/7gWY1iU8gRSd6RXul334DuFPLcj.jpg', null, null, 'a2NYVO58Tn4', '2026-11-12', 1.694, 0, 'tt43582400', null, null, null, null),
(1732866, '3726 mdpl', 'Petualangan', 100, 'NR', 'Adapted from a novel named “3726 mdpl”', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/aTVB2rSXPqNye3nkQiMLD2Y5VP3.jpg', null, null, null, '2026-12-03', 1.665, 0, 'tt43678558', null, null, null, null),
(1776255, 'Merah Sebelum Fajar', 'Drama', 113, 'NR', 'Amidst the volatile dawn of Indonesian independence, five individuals from starkly contrasting socio-political backgrounds must navigate a heavily fractured nation to deliver a critical state document, confronting severe hostility and paranoia from the very revolutionary factions they seek to serve.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/vfl94mcCkdkWX1VtyNPO7Tas7mC.jpg', 'https://image.tmdb.org/t/p/w1280/aeUIdBATp09Omnz0OLE2OP07uxE.jpg', null, null, '2026-10-27', 1.858, 0, null, null, null, null, null),
(1707669, 'Festival Hantu Lapar', 'Kengerian', 100, 'NR', 'After inadvertently violating a sacred ancestral taboo during the Hungry Ghost Festival, an adopted young man and his friends must break a relentless supernatural curse before the spiritual gates close permanently.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/xQo2xIQFKYq46iYEq4vByTPUK9s.jpg', 'https://image.tmdb.org/t/p/w1280/wa39eElPw7UWDZeQrzm8qglbqN0.jpg', null, '5XcAn0TLlGY', '2026-11-26', 1.831, 0, 'tt43611167', null, null, null, null),
(1642283, 'Filosofi Teras', 'Drama', 100, 'NR', 'Nea (Sherina Munaf) tulang punggung keluarga untuk ibunya; Ratih (Lydia Kandau), adiknya Runi (Zee Asadel), dan juga kakaknya Abi (Rangga Nattra) serta istrinya. Mendiang ayah mereka menjadikan rumahnya sebagai jaminan utang. Nea mengupayakan segala cara untuk membayarnya meskipun ia menyakiti orang yang ia sayangi. Namun, semakin keras Nea berusaha, semakin banyak pula masalah yang ia tidak bisa kendalikan. Bisakah Nea merelakan dan menyadari ia tidak bisa mengontrol semuanya?', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/nKByTwAkZ7CXfGce8PUS1tyP1j.jpg', 'https://image.tmdb.org/t/p/w1280/r4OFPR2SUCZ7Nx2xNRjeBCDdnSR.jpg', null, 'NSEh5W0Y4ek', '2026-12-24', 1.761, 0, 'tt40194341', null, null, null, null),
(1381071, 'ゴジラ-0.0', 'Cerita Fiksi', 135, 'NR', 'War reduced Japan to zero, and Godzilla plunged it into minus. Two years have passed since then, and the country has faced agonizing struggles to achieve recovery and finally reclaim its daily life. Just as humanity managed to cling to a hard-won peace, a new threat strikes, crushing hope in an instant.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/zpcoFlZwyLnBt7bb5wmvGDCdg06.jpg', 'https://image.tmdb.org/t/p/w1280/oqrYIDH4tvfEzPe1yqT4jzmAWHQ.jpg', null, 'pWJjYoqVSjQ', '2026-11-04', 22.537, 0, 'tt34384661', null, null, null, null),
(1433568, '粽邪4：坤蒂拉娜', 'Cerita Seru', 120, 'NR', 'When a forbidden Indonesian exorcism is broadcast live online, it unleashes a legendary demonic entity across Asia, forcing the grieving son of a Taiwanese victim to trace the curse back to its ancient, blood-soaked roots in rural Indonesia before it consumes everyone in its digital wake.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/6u8F23BammMeCWLvWITbFM2Nwbe.jpg', 'https://image.tmdb.org/t/p/w1280/2VDV1ZBHV1PKKBcWjRRCydZO1YR.jpg', null, null, '2026-10-23', 14.439, 0, 'tt38633224', null, null, null, null),
(656908, 'रामायण', 'Fantasi', 195, 'NR', 'An ancient epic follows a young prince and princess whose marriage and subsequent exile mark the beginning of a legendary journey. Their story of love, duty and destiny sets the stage for greater challenges ahead.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/gOWnXaBxqT6k2y40hKfYU6c0Ym.jpg', 'https://image.tmdb.org/t/p/w1280/ks72NqTPhpupk207NXiqmZIQQVI.jpg', null, 'AYkPRN874m8', '2026-11-06', 12.303, 0, 'tt27988879', null, null, null, null),
(607833, '인턴', 'Drama', 133, 'NR', 'A story about what happens when Seon-wu, the CEO of a fashion company who is more passionate than anyone when it comes to work, hires Ki-ho, who has a wealth of life experience, as a silver intern.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/9PX4rGgP1pXRlGcHkxzRsgvll8f.jpg', 'https://image.tmdb.org/t/p/w1280/OroFBNgB2RBzj2X65CweVhhQQG.jpg', 7, 'XMp9ietHc8A', '2026-10-30', 3.486, 3, 'tt43741215', 5.7, 59, null, null),
(1688795, '투모로우바이투게더 월드 투어 ‘액트 : 투모로우''', 'Musik', 97, 'NR', 'Like shining stars, TOMORROW X TOGETHER’s fourth world tour ''ACT : TOMORROW'' unfolds as a dazzling journey toward the tomorrow they promised together. From its beautiful storytelling to the stunning production and powerful live performances that captivated MOA around the world, experience the immersive energy of TOMORROW X TOGETHER’s spectacular world tour on the big screen!', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/aRoPHxYzfQjCLxSp4H4sJANNmou.jpg', 'https://image.tmdb.org/t/p/w1280/35hGgrsbnpuex4XpdAlnQG1ssvk.jpg', null, 'q0XKUFGn_M4', '2026-10-24', 2.002, 0, null, null, null, null, null),
(969681, 'Spider-Man: Brand New Day', 'Cerita Fiksi', 145, 'NR', 'Empat tahun setelah peristiwa Spider-Man: No Way Home, Peter Parker sudah tidak ada lagi dan Spider-Man kini berada di puncak kemampuannya dalam menjaga Kota New York tetap aman. Semuanya berjalan dengan baik hingga serangkaian kejahatan yang tidak biasa menyeret Spider-Man ke dalam jaring misteri yang lebih besar dari apa pun yang pernah ia hadapi sebelumnya. Untuk menghadapi apa yang akan datang, Spider-Man tidak hanya harus berada dalam kondisi fisik dan mental terbaiknya, tetapi juga harus siap menghadapi konsekuensi dari masa lalunya!', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/bjiS5ipwxb9JFy3XRRN4OAilSeX.jpg', 'https://image.tmdb.org/t/p/w1280/4tjxYg2AbOzzG9G1YuiT2NzYhlH.jpg', 8.5, 'P3uI5sLosKU', '2026-07-29', 713.423, 5519, 'tt22084616', 8, 327986, 'PG-13', 24090),
(1381078, 'Love of Your Life', 'Percintaan', 109, 'NR', 'Disutradarai Rachel Morrison, LOVE OF YOUR LIFE mengikuti Maya, yang pertemuannya dengan Charlie memicu kisah cinta luar biasa dan masa depan di luar bayangannya. Saat masa depan itu berubah, Maya dihadapkan pada kehidupan baru yang tak terduga, memaksanya memahami siapa dirinya, apa yang diinginkannya, dan cara mencintai lagi.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/dL3Tcv4FU2K85bgnGRBgLjFSrLr.jpg', 'https://image.tmdb.org/t/p/w1280/mqYqKvrKTgMvK50VtEDZlYFsnHz.jpg', 6.4, 'HzGx48E64Xg', '2026-10-07', 63.45, 34, 'tt34384900', null, null, 'R', 632),
(1291595, 'Insidious: Out of the Further', 'Kengerian', 106, 'NR', 'Gemma, a young mother raising her daughter in the house she grew up in, discovers she can travel into The Further, where she possesses an ability to bring what lives there back to the real world.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/4tTrW9dXCByS5wt2pXVWb58zNjz.jpg', 'https://image.tmdb.org/t/p/w1280/p40lmrdI4blcAPZQMTPaiy5v5Ym.jpg', 7.7, 'gXjurDkYnEM', '2026-08-19', 397.499, 741, 'tt32393988', 6.2, 13228, 'PG-13', 6148),
(1101383, 'The End of Oak Street', 'Cerita Fiksi', 100, 'NR', 'After a mysterious cosmic event rips Oak Street from suburbia and transports their neighborhood to someplace unknown, the Platt family soon discovers that their very survival depends on them sticking together as they navigate their now unrecognizable surroundings.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/nlC0I1cCemzfNLYPnAhdydpOYOi.jpg', 'https://image.tmdb.org/t/p/w1280/b9q9VmbXDvJmTziRqkwdEmFdwhr.jpg', 7.1, 'u4tgctWuHc0', '2026-08-12', 127.118, 2066, 'tt27165187', 6.5, 39062, 'PG-13', 4369),
(1492640, 'UNABOMBER', 'Cerita Seru', 101, 'NR', 'Di drama yang terinspirasi kisah nyata ini, jalan Ted Kaczynski dari seorang genius dan objek percobaan di Harvard sampai menjadi Unabomber terkuak saat FBI memburunya.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/39aMkR8Y5vhCG9dTkjiqRl8AVqp.jpg', 'https://image.tmdb.org/t/p/w1280/58D9nalUYW5L5K0guw7hcpsEJBH.jpg', 6.6, 'B3tR6qQjbgI', '2026-09-25', 45.37, 460, 'tt6933238', 6.2, 10808, 'R', 3145),
(687163, 'Project Hail Mary', 'Cerita Fiksi', 157, 'NR', 'Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/iOb2fjXLbpJgyQXe46n1WtGCnaa.jpg', 'https://image.tmdb.org/t/p/w1280/8Tfys3mDZVp4tNoH2ktm06a0Tau.jpg', 8.6, 'NKYea63tQmI', '2026-03-15', 101.949, 8310, 'tt12042730', 8.2, 570200, 'PG-13', 1789),
(1084244, 'Toy Story 5', 'Animasi', 102, 'NR', 'When Bonnie receives a Lilypad tablet as a gift and becomes obsessed, Buzz, Woody, Jessie and the rest of the gang''s jobs become exponentially harder when they have to go head to head with the all-new threat to playtime.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/sfQtVlIHljToOwYjhe21KPGzZWK.jpg', 'https://image.tmdb.org/t/p/w1280/qjTqY5coNiz6sVtPng40IzltsoN.jpg', 8.3, 'QftAW9TTmuQ', '2026-06-17', 157.404, 2618, 'tt29355505', 7.4, 81658, 'PG', 2148),
(1137844, 'Mayday', 'Aksi', 111, 'NR', 'Saat seorang pilot Angkatan Laut AS dalam misi rahasia selama Perang Dingin terjebak di belakang garis musuh, satu-satunya peluang untuk bertahan hidup adalah menjalin aliansi dengan seorang mantan agen KGB eksentrik.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/hVXjX1jLZ1ljFSNGXpjJfbTUOa7.jpg', 'https://image.tmdb.org/t/p/w1280/g7Ccid5kuD7A8hXWlsQiNfwOxaD.jpg', 7.9, 'om5Un9X720M', '2026-09-03', 25.912, 958, 'tt28014327', 6.9, 9404, 'PG-13', 2172),
(1081003, 'Supergirl', 'Aksi', 108, 'NR', 'When an unexpected and ruthless adversary strikes too close to home, Kara Zor-El, aka Supergirl, reluctantly joins forces with an unlikely companion on an epic, interstellar journey of vengeance and justice.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/qn4wWonvYGQbf8X4s2VwIqv1acc.jpg', 'https://image.tmdb.org/t/p/w1280/heZQmyNvkH236ha2M3JckdUQQqb.jpg', 6.7, 'rbLyjarG_bU', '2026-06-24', 89.769, 2574, 'tt8814476', 5.8, 89480, 'PG-13', 1244),
(950028, 'The Invite', 'Komedi', 107, 'NR', 'Joe and Angela''s marriage is on thin ice. When they invite their enigmatic upstairs neighbors for a dinner party, the night spirals into unexpected places. Have they reignited the spark or lit the match that burns it all down?', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/b7Dr8Chzse8VagexAporUu2RtLx.jpg', 'https://image.tmdb.org/t/p/w1280/lEwqBGNR65KZv6Ej5ufcmhZu2y2.jpg', 7.2, 'nelkiuezJxg', '2026-06-25', 31.754, 798, 'tt14173636', 7.5, 68555, 'R', 1369),
(1433367, 'One Night Only', 'Percintaan', 103, 'NR', 'Two love-starved strangers crash into each other on the one night of the year when single people are allowed to have sex.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/f1v8IcYcQggeq1N0unoMJMrzTd9.jpg', 'https://image.tmdb.org/t/p/w1280/3afHil7EVm655wO2NS6RHxuyicE.jpg', 6.4, 'AvKoSR3O4NQ', '2026-08-06', 28.826, 207, 'tt37853455', 6.3, 6744, 'R', 1177),
(1368166, 'The Housemaid', 'Misteri', 131, 'NR', 'Berusaha melarikan diri dari masa lalunya, Millie Calloway menerima pekerjaan sebagai pembantu rumah tangga yang tinggal bersama pasangan kaya Nina dan Andrew Winchester. Namun, apa yang awalnya merupakan pekerjaan impian dengan cepat berubah menjadi sesuatu yang jauh lebih berbahaya—permainan rahasia, skandal, dan kekuasaan yang seksi dan menggoda.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/cWsBscZzwu5brg9YjNkGewRUvJX.jpg', 'https://image.tmdb.org/t/p/w1280/zTnAnYIn0Iv3cn0ZHlzLhou3ybm.jpg', 7.3, 'uhBGfnarVx8', '2025-12-18', 46.474, 3220, 'tt27543632', 6.7, 203278, 'R', 928),
(1003596, 'Avengers: Doomsday', 'Cerita Fiksi', 165, 'NR', 'Tiga semesta bertabrakan. Para pahlawan favorit kini berada di ambang kehancuran, bersiap menghadapi ancaman terbesar yang belum pernah ada dalam sejarah mereka.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/sLYCyO58UvBuBtbHTQjPCCgJ4dG.jpg', 'https://image.tmdb.org/t/p/w1280/g3gpP5YDbA85DsA0bt5mgGQIe5q.jpg', null, 'PyTEUYXVDaU', '2026-12-18', 139.565, 0, 'tt21357150', null, null, null, null),
(1170608, 'Dune: Part Three', 'Cerita Fiksi', 140, 'NR', 'Bagian ketiga dan terakhir dari trilogi Dune karya Villeneuve. Berdasarkan novel Dune Messiah karya Frank Herbert.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/d43fvHQsIMa4kpyhKXw0haEJIvI.jpg', 'https://image.tmdb.org/t/p/w1280/i5E9H7Ik0u61ylDDTbmUpTL3Yw.jpg', null, 'NdvqHc56lE0', '2026-12-15', 28.565, 0, 'tt31378509', null, null, null, null),
(911916, 'Spider-Man: Beyond the Spider-Verse', 'Animasi', 100, 'NR', 'Hunted by Miguel O''Hara''s Spider Society and betrayed by his friends, Miles finds himself in the darkest corners of the Spider-Verse in search of a way home. Knowing that his family has been not only fractured but endangered by his calling, it''s a race against the clock for Miles to travel across the wildest reaches of time and space to fight for and reunite everything he holds most dear.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/9KAe39xqyZnv9J4W3DRGdQqX82h.jpg', 'https://image.tmdb.org/t/p/w1280/fUcT8bcJD3SZsy84Z9QRP6kOS7v.jpg', null, null, '2027-06-16', 7.209, 0, 'tt16360004', null, null, null, null),
(421892, 'Shrek 5', 'Komedi', 100, 'NR', 'Shrek and Donkey team up for another whirlwind, big-city adventure, this time in the magical city of Further Further Away.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/m9jLiemA7t2umlXKptDwtIUHU8l.jpg', 'https://image.tmdb.org/t/p/w1280/wHbZr627WHFPMpfskRwX6NBgjxv.jpg', null, 'Swiz1XyfhcI', '2027-06-30', 13.189, 0, 'tt6113186', null, null, null, null),
(1300968, 'The Hunger Games: Sunrise on the Reaping', 'Cerita Fiksi', 158, 'NR', 'Return to the world of Panem 24 years before the events of The Hunger Games, starting on the morning of the reaping of the 50th Hunger Games, also known as the Second Quarter Quell.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/jNcZH8yplxttRlf0wwqfGGMKHxX.jpg', 'https://image.tmdb.org/t/p/w1280/aqFZcr2dxSZ2UwWSo1WC6C0rwDf.jpg', null, 'Dr060OLTodE', '2026-11-18', 18.13, 0, 'tt32558705', null, null, null, null),
(1260649, 'Jumanji: Open World', 'Petualangan', 100, 'NR', 'Our heroes have escaped the ever-changing jungles of Jumanji before, but this time the game comes to us - as Jumanji breaks free of its console, unleashing its chaos into our world.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/qv0X60rC2SUWVvOkbgixpRoOSoq.jpg', 'https://image.tmdb.org/t/p/w1280/pYN5Zjc3l1hj2hMeBbzRYDYTC1E.jpg', null, 'zhApeaHMvfs', '2026-12-23', 8.696, 0, 'tt26735127', null, null, null, null),
(1147572, 'Narnia: The Magician''s Nephew', 'Fantasi', 100, 'NR', 'Two children discover a wood full of pools leading to other worlds. One takes them to a dead city beneath a dying sun, where they wake a queen who exterminated its population and accidentally bring her back to London.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/yrqR0qquy4JOfqZCsFJV7vJoOSh.jpg', 'https://image.tmdb.org/t/p/w1280/xfSMUdnYplhEtLZDFPsOiSBOpU5.jpg', null, 'gDJ-ini7fF0', '2027-02-10', 21.662, 0, 'tt9077514', null, null, null, null),
(1417668, 'Star Wars: Starfighter', 'Cerita Fiksi', 100, 'NR', 'An original story set approximately five years after the events of Star Wars: The Rise of Skywalker.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/6LJetiEQjXUE9kDpXavXpZN1Vjk.jpg', 'https://image.tmdb.org/t/p/w1280/oVjiUAsIQ4WZ9W6p7ElnXneoho3.jpg', null, null, '2027-05-26', 3.05, 0, 'tt28069611', null, null, null, null),
(1177369, 'The Legend of Zelda', 'Aksi', 100, 'NR', 'A live-action adaptation of Nintendo''s Legend of Zelda video game series.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/4XuaHHQ5eR9czPZPHcaaUjekx5w.jpg', 'https://image.tmdb.org/t/p/w1280/7iHZruybsGB7g9vrm9eeypzmpV1.jpg', null, null, '2027-04-28', 4.628, 0, 'tt29873948', null, null, null, null),
(1401586, 'Sonic the Hedgehog 4', 'Komedi', 100, 'NR', 'Sonic the Hedgehog, joined by a new hero named Amy, faces a new technological nemesis known as Metal Sonic.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/t8uoHBODkFlSQJRL6qc4IclUBlH.jpg', 'https://image.tmdb.org/t/p/w1280/4Sh2c33WHf1KxX8UYuYLIroaVEv.jpg', null, null, '2027-03-11', 12.83, 0, 'tt16744566', null, null, null, null),
(1384758, 'Ice Age: Boiling Point', 'Petualangan', 103, 'NR', 'A dinosaur-and-lava-filled madcap adventure takes Manny, Sid, Diego, Ellie, Buck, acorn-obsessed Scrat – this time joined by Baby Scrat and the enormous Jurassic Scrat – and the rest of the herd to visit never before-seen corners of the treacherous Lost World.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/mPhAreyZLLcZ9pl4KRyEaqSu1Zv.jpg', 'https://image.tmdb.org/t/p/w1280/pJfMliqzzVzTU634zpYDMfYNX6c.jpg', null, null, '2027-01-28', 19.303, 0, 'tt34512981', null, null, null, null),
(1400336, 'Focker-in-Law', 'Komedi', 105, 'NR', 'Henry, son of Greg and Pam Focker, faces family chaos when he decides to marry a strong-willed woman who appears to be his complete mismatch.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/gPdzdeehaoaYqxH2rA6yayEDSsS.jpg', 'https://image.tmdb.org/t/p/w1280/nubnNXuMArUhiDW1nUevGsG65x9.jpg', null, '9CKu3WoMYCg', '2026-11-25', 12.474, 0, 'tt34966140', null, null, null, null),
(1324923, 'A Quiet Place Part III', 'Kengerian', 100, 'NR', 'The third installment in the franchise. Plot TBA.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/37XcaePjgtaga0gB3dFNSc7QnuS.jpg', 'https://image.tmdb.org/t/p/w1280/t9FIKABadNBLQaHTu3jnmT5tnhL.jpg', null, null, '2027-07-28', 2.733, 0, 'tt36495786', null, null, null, null),
(1440769, 'The Beekeeper 2', 'Aksi', 100, 'NR', 'Former government assassin and wanted man Adam Clay is tasked with stopping rogue Beekeepers attempting to take over the government.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/kYr0WsY1SEGfpUrLKSpvNmtoXQ3.jpg', 'https://image.tmdb.org/t/p/w1280/smdkH5T2xiK30dHWPm2LfJcdPME.jpg', null, '5HK3wimDxBI', '2027-01-13', 9.787, 0, 'tt35935357', null, null, null, null),
(1288438, 'Godzilla x Kong: Supernova', 'Cerita Fiksi', 100, 'NR', 'Features several new human characters alongside the beloved and iconic Titans Godzilla and Kong as they face off against a cataclysmic world-ending threat.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/gEGDDG6QMDFZ1sV32CGxvzaVPnv.jpg', 'https://image.tmdb.org/t/p/w1280/gLjZC1YGcujC82DF5subtEXWg7F.jpg', null, null, '2027-03-25', 6.244, 0, 'tt32561550', null, null, null, null),
(1421903, 'Werwulf', 'Kengerian', 120, 'NR', 'A harrowing tale of devotion, damnation and the devil within.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/imnkSt4PSQpxIuyiRpJCiLk3SZz.jpg', 'https://image.tmdb.org/t/p/w1280/jmW9NkzbpI9vhyxJU2x644Nj7VU.jpg', null, 'CL1EFACsWag', '2026-12-25', 7.967, 0, 'tt35514120', null, null, null, null),
(1458319, 'How to Train Your Dragon 2', 'Aksi', 100, 'NR', 'The second live-action adaptation of the animated trilogy. Plot TBA.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/6VlnDSuTmBPW6a45Qxp5qeDINBq.jpg', null, null, null, '2027-06-10', 3.305, 0, 'tt36416299', null, null, null, null),
(1457866, 'THE FURTHER MIS-ADVENTURES OF CLIFF BOOTH', 'Drama', 100, 'NR', 'Eight years after the events of Once Upon a Time in... Hollywood, Cliff Booth returns to a changing Los Angeles. Now working as a fixer in the shadows of the Hollywood studio system, Cliff finds himself entangled in a dangerous web of secrets, crimes and betrayals that will test everything he knows about loyalty and survival.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/6aS1fKh5Z8Vf9n7wWtVAe86BHVG.jpg', 'https://image.tmdb.org/t/p/w1280/aRO4TuqF8dkRCb5tPlsSlpJbmQD.jpg', null, 'RjEZaUBbUvU', '2026-11-25', 6.718, 0, 'tt36408401', null, null, null, null),
(1306322, 'Spaceballs: The New One', 'Komedi', 100, 'NR', 'Forty years after the events of the first Spaceballs, the galaxy is once again under threat. A threat so evil, so unstoppable, so completely lacking in any original ideas, that it has vowed to bring back the past... every last bit of it. With Lone Starr in hiding, Queen Vespa on the throne, and the Schwartz stretched thinner than a franchise releasing TV episodes theatrically, the only hope for the galaxy is Vespa''s undisciplined son, Prince Starburst, and a mysterious Palace advisor named Destiny. Together, they must find Lone Starr, Yogurt, and any other iconic legacy characters fans are demanding before they discover the hard way that, while some threats you can fight, the reboot is not one of them.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/9usPcpMm8GhzkHIXqiklhPrflY3.jpg', 'https://image.tmdb.org/t/p/w1280/6dOmk6RoedeTSelTj2b473xThZH.jpg', null, null, '2027-04-22', 3.619, 0, 'tt32659463', null, null, null, null),
(1078446, 'Violent Night 2', 'Aksi', 110, 'NR', 'When Santa forgets the true meaning of Christmas, he finds himself in the heart of a lively mall community in desperate need of his help. Sapped of his magic, he’ll need another way to take on the goons threatening the mall, and time is running out. Santa has to rediscover his faith in goodness and call in some last-minute reinforcements from the one person no baddie wants to tangle with: Mrs. Claus.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/7HPvgItDw9NgW3iy4tFRRuGNbuN.jpg', 'https://image.tmdb.org/t/p/w1280/78dChJs7doULSEhIiOvGUcXQRGU.jpg', null, 'FmM2giDwLAE', '2026-12-02', 8.459, 0, 'tt32432428', null, null, null, null),
(791523, 'Wildwood', 'Animasi', 130, 'NR', 'Prue and her classmate Curtis are drawn into a magical forest filled with enchanted creatures, loyal allies, and formidable adversaries as they embark on a desperate quest to rescue Prue''s abducted baby brother from a murder of crows led by a mysterious woman named Alexandra.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/snFM00mpNAfUzUtkdEW0uDEvXA0.jpg', 'https://image.tmdb.org/t/p/w1280/sl5NJ1vtyhP9Vr88bB4blULsJYp.jpg', null, 'bJQGtSeLPII', '2026-10-19', 15.764, 0, 'tt2056785', null, null, null, null),
(1437511, 'How to Rob a Bank', 'Aksi', 122, 'NR', 'A crew of social media-savvy bank robbers broadcasts their daring heists, unaware that their growing viral fame has put them in the crosshairs of a veteran FBI agent and a brilliant software engineer. Despite the unlikely duo closing in, the crime ring pushes past their limits, putting everything on the line for their most ambitious heist yet.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/ifYDZkr2qkHFz87TNVvlxajOxl5.jpg', 'https://image.tmdb.org/t/p/w1280/xghtLO90cQPybH85aw1C3bZ2P3.jpg', null, 'MVvWKh336m4', '2026-11-11', 7.436, 0, 'tt35866986', null, null, 'R', null),
(1523140, 'Man of Tomorrow', 'Aksi', 100, 'NR', 'Superman and Lex Luthor find themselves forced to work together—to a certain degree—against a much, much bigger threat when Brainiac sets his sights on Earth.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/tYLgfKk3cEk7LskgxWyW37Nty01.jpg', 'https://image.tmdb.org/t/p/w1280/lX2TpAZxdIus6cnMCDBOrs96NBY.jpg', null, null, '2027-07-07', 6.186, 0, 'tt37833661', null, null, null, null),
(1538497, 'Hexed', 'Petualangan', 99, 'NR', 'An impulsive and unconventional teenage girl named Billie discovers secret magical abilities which, once unleashed, hurtle her into a spectacle-filled journey out of suburbia and into a vast witch realm called Hexe. Forced to team up with her cautious mother, Alice, they uncover family mysteries that could change the world of witches forever.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/yykeYKbDBM9eUMJUucaaDo2mi1p.jpg', 'https://image.tmdb.org/t/p/w1280/wZ9Me7OndzgBOEAa8nSBNPu3Sl4.jpg', null, 'KXO21xZdUaM', '2026-11-25', 19.402, 0, 'tt38077943', null, null, null, null),
(1300926, 'The Angry Birds Movie 3', 'Animasi', 96, 'NR', 'Red faces his greatest challenge yet - surviving fatherhood - while saving the world.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/oxaW6X3xohnzdFSBKCrCjRDckMe.jpg', 'https://image.tmdb.org/t/p/w1280/ieAytQ8YcWEZGQpbBy7vHVddwd.jpg', null, 'a9DB_aUMzME', '2026-12-23', 8.588, 0, 'tt32557122', null, null, null, null),
(1567605, 'Ebenezer', 'Fantasi', 120, 'NR', 'An elderly miser embarks on a supernatural journey after visits from the ghost of his former business partner and the Spirits of Christmas Past, Present, and Yet to Come force him to confront his past and fight for a second chance at happiness.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/6H2N59jJW1hZEzn2ZdrMvJw5vNI.jpg', 'https://image.tmdb.org/t/p/w1280/bG8uwYAq5Y9bPDaoxq2eHjopA9T.jpg', null, 'l_Ozo1xUgbU', '2026-11-11', 15.013, 0, 'tt38773219', null, null, null, null),
(858035, 'Klara and the Sun', 'Cerita Fiksi', 117, 'NR', 'An Artificial Friend named Klara finds a deep bond with a troubled young girl, bringing light and hope to a grieving family through her unwavering devotion and innocent wonder.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/xqovj2p6HRsgHxN81qYAYF4StgM.jpg', 'https://image.tmdb.org/t/p/w1280/s4E7NDJCOG3wqc5psv2RLr9QfUm.jpg', null, 'wixzainceAE', '2026-10-21', 16.068, 0, 'tt14371256', null, null, null, null),
(891621, 'Wild Horse Nine', 'Komedi', 117, 'NR', 'Shortly before the 1973 Chilean coup, CIA agents Chris and Lee are dispatched from Santiago to Easter Island by their bureau chief, MJ. Amongst the Island''s iconic statues, and as the longtime partners wrestle with their dark pasts and present conspiracies, Chris''s newfound bond with a pair of rebellious students threatens to send everyone’s trip to this remote paradise sideways.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/dNJFRtVg3xLQ7dbNIQ55cmmIniD.jpg', 'https://image.tmdb.org/t/p/w1280/b17UWf3LqHgKolQkXckne32qv0.jpg', null, 'kqxuamKxRTo', '2026-10-30', 12.633, 0, 'tt15799564', null, null, null, null),
(1195803, 'Wicker', 'Percintaan', 105, 'NR', 'On the outskirts of a village by the sea, lives a Fisherwoman; smelly, single and perpetually ridiculed. One day, fed up with her stuffy, small-minded neighbours, she commissions herself a husband to be made from wicker. In an otherwise conservative town, this unconventional romance sparks outrage, jealousy and chaos.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/eOYkNDalgt1v6UGjw3AoFR5qo9D.jpg', 'https://image.tmdb.org/t/p/w1280/xVh1ypMoVkMf5IB7y3hnRplJ14c.jpg', null, 'UVAki9SGrlg', '2026-10-21', 13.306, 0, 'tt29611136', 7.4, 376, 'R', null),
(1497464, 'Gatto', 'Animasi', 100, 'NR', 'After years of maneuvering the canal-ridden, superstitious city of Venice, Italy, a scrappy black cat named Nero begins to question whether he’s lived the right lives. Indebted to Rocco, a ruthless local feline mob boss, Nero finds himself in a quandary and is forced to forge a truly unexpected friendship that may finally lead him to his purpose — unless Venice gets the better of him first.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/bgt6dSrwkJCMqdKWRpN4ZTAd1kL.jpg', 'https://image.tmdb.org/t/p/w1280/etB2OT0nUknOAPZV7EgbEbt6HJh.jpg', null, null, '2027-03-03', 21.792, 0, 'tt26443610', null, null, null, null),
(1286656, 'I Play Rocky', 'Drama', 128, 'NR', 'The electrifying true story about an unknown actor with an unshakable belief that he wasn''t just meant to write Rocky—he was meant to be Rocky Balboa. Told "no" at every turn, Sylvester Stallone bets everything on himself, holding the line on playing the lead against seemingly impossible odds.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/xE5tY3lppZUyG7WKKThsuYHuAHr.jpg', 'https://image.tmdb.org/t/p/w1280/1lnnjBCRLZzKRhQipK5zm61YkPe.jpg', null, 'Kpc4o2J28QE', '2026-11-06', 7.926, 0, 'tt11995650', null, null, null, null),
(1156621, 'Teenage Mutant Ninja Turtles: Mutant Mayhem 2', 'Aksi', 100, 'NR', 'Donnie, Raph, Leo, and Mikey are back for their next adventure with Master Splinter, the Mutants, April, and a new villain they have to face: The Shredder.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/yukp9qq3JmgatfMSGnxdyn6jtRX.jpg', 'https://image.tmdb.org/t/p/w1280/dYsXhu97sNCQbObZjq3awyrdoaf.jpg', null, null, '2027-08-12', 2.68, 0, 'tt31512072', null, null, null, null),
(1425859, 'Remain', 'Percintaan', 100, 'NR', 'When reclusive architect Tate Gordon moves to small coastal town to complete his latest project, he encounters an alluring young woman who pulls him out of his shell, and into the center of a deadly mystery that hangs over the town.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/5hPNq5h2y8Ux6nPBRMEwZ8npVTp.jpg', 'https://image.tmdb.org/t/p/w1280/tWUizVQOYarekT6JRqPtQogIY3s.jpg', null, null, '2027-02-03', 11.253, 0, 'tt35621542', null, null, null, null),
(1117898, 'The Cat in the Hat', 'Animasi', 114, 'NR', 'Assigned his toughest mission yet, the Cat must cheer up siblings Gabby and Sebastian as they adjust to life in a new town. Known for pushing boundaries, this agent of chaos must prove himself or risk losing his magical hat forever.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/mWN6knIVJ2o7eGwSm7mOgSCwNUc.jpg', 'https://image.tmdb.org/t/p/w1280/9y9o686DsQg0KzPtERzcW7Cf8IE.jpg', null, 'tkZpcypT8Z4', '2026-11-04', 13.236, 0, 'tt2321555', null, null, null, null),
(1297467, 'The Exorcist: Martyrs', 'Kengerian', 100, 'NR', 'Thirteen years ago, New York City detective Julie Miller ended the terror reign of satanic serial killer Father Sunday. The case made her a hero, and she has thrown herself into her work ever since. Now a new killer scrawls her name in an altar boy''s blood on the walls of a church crypt, dragging her back into the darkness she believed she had buried with him.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/i3kvS445sWWIhuxgXywPuUcsoP0.jpg', 'https://image.tmdb.org/t/p/w1280/ePIY6b8TlIjqFzK1JKANPhxUIPn.jpg', null, 'iIEYfH-jg1Y', '2027-03-10', 16.588, 0, 'tt32492552', null, null, null, null)
on conflict (tmdb_id) do update set
  title = excluded.title,
  genre = excluded.genre,
  duration_min = excluded.duration_min,
  synopsis = excluded.synopsis,
  poster_url = excluded.poster_url,
  backdrop_url = excluded.backdrop_url,
  vote_average = excluded.vote_average,
  trailer_key = excluded.trailer_key,
  release_date = excluded.release_date,
  popularity = excluded.popularity,
  vote_count = excluded.vote_count,
  -- data IMDb tidak ditimpa dengan kosong kalau kali ini OMDb tidak dipakai
  imdb_id = coalesce(excluded.imdb_id, movies.imdb_id),
  imdb_rating = coalesce(excluded.imdb_rating, movies.imdb_rating),
  imdb_votes = coalesce(excluded.imdb_votes, movies.imdb_votes),
  age_rated = coalesce(excluded.age_rated, movies.age_rated),
  watchers = excluded.watchers;

-- Jadwal 7 hari ke depan di semua bioskop.
-- Fungsi ini dibuat oleh supabase-cinema-auth.sql, jadi file itu harus dijalankan lebih dulu.
select refresh_showtimes(7) as jadwal_baru_dibuat;
